using Cysharp.Threading.Tasks; using UnityEngine;
namespace Demo.Inventory { public sealed class InventoryRuntime:MonoBehaviour { public static InventoryRuntime Instance{get;private set;} public InventoryService Service{get;private set;} InventoryDatabase db; async void Awake(){if(Instance!=null){Destroy(gameObject);return;}Instance=this;DontDestroyOnLoad(gameObject);db=new InventoryDatabase();await db.InitializeAsync();if(this==null)return;Service=new InventoryService(db);Service.AddItem(1002,20);Service.AddItem(1001,80);Service.AddItem(1003,3);}void OnDestroy(){db?.Release();} } }
